import { Accordion } from "@leeward/react";

export function FeesFaq() {
  return <Accordion items={[{ value: "fees", title: "What does a transfer cost?", content: "Free between Leeward accounts." }]} />;
}

import { Alert, Button } from "@leeward/react";

export function LimitWarning() {
  return (
    <Alert tone="warning" title="You are close to your daily limit" actions={<Button size="sm">Raise limit</Button>}>
      ₺1.500 left today. Limits reset at midnight.
    </Alert>
  );
}

import { Avatar } from "@leeward/react";

export function Recipient() {
  return <Avatar name="Deniz Yılmaz" />;
}

import { AvatarGroup } from "@leeward/react";

export function JointAccount() {
  return <AvatarGroup people={[{ name: "Deniz Yılmaz" }, { name: "Ece Kaya" }, { name: "Can Öztürk" }, { name: "Elif Şahin" }]} max={3} />;
}

import { Badge } from "@leeward/react";

export function PendingBadge() {
  return <Badge tone="warning">Pending</Badge>;
}

import { Banner, Link } from "@leeward/react";

export function Maintenance() {
  return (
    <Banner tone="warning" action={<Link href="#schedule">See the schedule</Link>} onDismiss={() => {}}>
      Card payments may fail between 02:00 and 04:00 on Sunday.
    </Banner>
  );
}

import { Breadcrumbs } from "@leeward/react";

export function StatementPath() {
  return (
    <Breadcrumbs
      items={[
        { label: "Accounts", href: "/accounts", icon: "home" },
        { label: "Everyday", href: "/accounts/everyday" },
        { label: "Statements" },
      ]}
    />
